package com.gomgomapps.math.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class ThreeNumberEstimationTest {
 @Test public void publicThreeTermsDistinguishEstimateFromExactSum(){Question q=ThreeNumberEstimation.make(247,386,104,10);q.answers=new String[]{"poison"};assertTrue(ThreeNumberEstimation.check(q,List.of("740")).correct());assertFalse(ThreeNumberEstimation.check(q,List.of("737")).correct());assertEquals(11,q.studyGuide.frames.size());assertFalse(q.studyGuide.transfer);assertEquals("740",q.studyGuide.frames.get(10).expected);}
 @Test public void zeroHalfCarryAndEstimateAboveOriginalMillionRemainCorrect(){for(int unit:List.of(10,100,1000,10000,100000))for(int n:List.of(0,unit/2-1,unit/2,999999,1000000)){Question q=ThreeNumberEstimation.make(n,0,0,unit);int expected=(n/unit+(n%unit>=unit/2?1:0))*unit;assertTrue(ThreeNumberEstimation.check(q,List.of(""+expected)).correct());}Question q=ThreeNumberEstimation.make(350000,350000,300000,100000);assertTrue(ThreeNumberEstimation.check(q,List.of("1100000")).correct());assertFalse(ThreeNumberEstimation.check(q,List.of("1000000")).correct());}
 @Test public void malformedPublicConditionsAndInputsDoNotUseHiddenAnswers(){Question q=ThreeNumberEstimation.make(10,20,30,10);for(String raw:List.of("","abc","-1","01","10+20"))assertEquals(Checker.Status.INPUT_NEEDED,ThreeNumberEstimation.check(q,List.of(raw)).status);q.prompt=q.prompt.replace("10 + 20 + 30","1000000 + 1000000 + 1000000");assertNull(ThreeNumberEstimation.read(q));assertEquals(Checker.Status.INPUT_NEEDED,ThreeNumberEstimation.check(q,List.of("3000000")).status);}
 @Test public void compactIndexMatchesAllSmallTriples(){for(int maximum=0;maximum<=7;maximum++){long index=0;for(int a=0;a<=maximum;a++)for(int b=0;b<=maximum-a;b++)for(int c=0;c<=maximum-a-b;c++)assertArrayEquals(new int[]{a,b,c},ThreeNumberEstimation.at(maximum,index++));assertEquals(index,ThreeNumberEstimation.combinations(maximum));}assertEquals(166667666668500001L,ThreeNumberEstimation.combinations(1000000));}
 @Test public void smallDomainFreshThenOldest(){var limits=new CurriculumLimits("wholeMaximum=2;roundingUnits=10");Generator g=new Generator(new Random(258));List<String> recent=new ArrayList<>();for(int i=0;i<10;i++){Question q=g.next(ThreeNumberEstimation.ID,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());}assertEquals(recent.get(0),g.next(ThreeNumberEstimation.ID,recent,false,limits).signature());}
 @Test public void actualPipelineAllFiveUnitsAndPublicHelp(){var limits=GlobalCurriculum.limits("na-nied-primary-2024-v1",ThreeNumberEstimation.ID,6);Generator generator=new Generator(new Random(259));List<String> recent=new ArrayList<>();Set<Integer> units=new HashSet<>();for(int i=0;i<150;i++){Question q=generator.next(ThreeNumberEstimation.ID,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var g=ThreeNumberEstimation.read(q);assertTrue((long)g.first()+g.second()+g.third()<=1000000);units.add(g.unit());int expected=0;for(int n:g.terms())expected+=(n/g.unit()+(n%g.unit()>=g.unit()/2?1:0))*g.unit();q.answers=new String[]{"poison"};assertTrue(new Checker().check(q,List.of(),List.of(""+expected)).correct());HelpPlan h=HelpPlan.forQuestion(q);assertEquals(11,h.size());assertFalse(h.canTransfer());assertTrue(h.step(10).accepts(""+expected));}assertEquals(Set.of(10,100,1000,10000,100000),units);}
}
